import { supabase } from '../supabaseClient';

// API Service Layer for centralized data fetching
export const apiService = {
  // Employee APIs
  employees: {
    getAll: async (page = 1, limit = 50, search = '') => {
      let query = supabase
        .from('employees')
        .select(`
          id,
          full_name,
          employee_id,
          department,
          position,
          email,
          phone,
          location,
          hire_date,
          profile_picture,
          photo_url,
          created_at,
          performance_rating,
          termination_date,
          reporting_manager:reporting_manager_id (
            full_name,
            employee_id
          )
        `)
        .order('created_at', { ascending: false });

      if (search) {
        query = query.or(`full_name.ilike.%${search}%,department.ilike.%${search}%,position.ilike.%${search}%,employee_id.ilike.%${search}%,phone.ilike.%${search}%,location.ilike.%${search}%`);
      }

      const from = (page - 1) * limit;
      const to = from + limit - 1;

      // First get the total count
      const { count: totalCount } = await supabase
        .from('employees')
        .select('*', { count: 'exact', head: true });

      // Then get the paginated data
      const { data, error } = await query.range(from, to);

      if (error) throw error;

      return { data, count: totalCount };
    },

    getById: async (id) => {
      const { data, error } = await supabase
        .from('employees')
        .select(`
          *,
          reporting_manager:reporting_manager_id (
            full_name,
            employee_id
          ),
          assets (
            id,
            name,
            type,
            status
          )
        `)
        .eq('id', id)
        .single();

      if (error) throw error;
      return data;
    },

    create: async (employeeData) => {
      const { data, error } = await supabase
        .from('employees')
        .insert(employeeData)
        .select()
        .single();

      if (error) throw error;
      return data;
    },

    update: async (id, employeeData) => {
      // Clear any existing profile picture if it's being set to null
      if (employeeData.profile_picture === null || employeeData.photo_url === null) {
        // Force a cache invalidation for this employee
        employeeData.updated_at = new Date().toISOString();
      }

      const { data, error } = await supabase
        .from('employees')
        .update(employeeData)
        .eq('id', id)
        .select()
        .single();

      if (error) throw error;
      return data;
    },

    delete: async (id) => {
      const { error } = await supabase
        .from('employees')
        .delete()
        .eq('id', id);

      if (error) throw error;
      return true;
    }
  },

  // Asset APIs
  assets: {
    getAll: async (page = 1, limit = 50, filters = {}) => {
      let query = supabase
        .from('assets')
        .select(`
          id, 
          name, 
          type, 
          status, 
          created_at, 
          assigned_to,
          asset_code,
          lpo_number,
          purchase_price,
          purchase_date,
